// Extrait le texte et l'expéditeur, quelle que soit la forme du payload WhatsApp
const j = $input.item.json;
let msg = null, from = null;
try {
  const value = j.entry?.[0]?.changes?.[0]?.value || j.value || j;
  const m = (value.messages || j.messages)?.[0];
  if (m) { from = m.from; msg = m.text?.body || m.button?.text || m.interactive?.list_reply?.title || ''; }
} catch (e) {}
if (!from && j.messages) { from = j.messages[0]?.from; msg = j.messages[0]?.text?.body; }
if (!msg) { return []; } // ignore les accusés de réception / statuts
return { json: { from, text: msg } };

